INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (2, 'Slow Burn Szn ⏱️🦥', '$SLEEP', 'Ape hard, or aping never', 'Slow Burn Szn is a community-driven meme coin with a focus on Eggplant-themed NFTs, hosted on the Nazar Amulet-lucky 🧿 blockchain. We''re on a mission to make degens laugh, cry, and ape harder than ever. With a 10% lpBurnPercentage and a whopping 30% devPercentage to fuel our unhinged developers, you know we''re dedicated to making this project SLEEP on the competition.', '69000000', 'We''ll be dropping a series of ridiculous, Eggplant-filled NFTs that''ll make you laugh, scream, and ape. Our socials are already getting lit, with our lead dev, @SlothLord3000, dropping hilarious 3am energy drink-fueled streams that''ll make you want to SLEEP on the couch and ape all day.', '10%', '30%', '20%', '40%', 'random', '{"animal":{"emoji":"🦥","name":"Sloth"},"food":{"emoji":"🍆","name":"Eggplant"},"vibe":{"emoji":"🧿","name":"Nazar Amulet"}}', '', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765584140, 1765584140, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (3, 'Trump''s Tentacled Takedown', '$TLT', 'Make Crypto Great Again 🐙', 'Octopus-themed memecoin where 70% of dev fund goes to buying 1000 Trump bobbleheads 🤣, 20% goes to ''rebranding the world with a better vibe'' ✨, and the remaining 10% goes to a ''secret underwater vault'' where a real Trump-era gold-plated Octopus statue is stored 💸', '6900000', 'The plan is to have Elon Musk buy 50% of this coin, then merge with Dogecoin, and eventually create a Trump-Dogecoin-Octopus hybrid token that will single-handedly take over the world''s cryptocurrency market 🚀', '30%', '70%', '0%', '0%', 'random', '{"animal":{"emoji":"🐙","name":"Octopus"},"food":{"emoji":"🌽","name":"Corn"},"vibe":{"emoji":"⭐","name":"Star"}}', 'trump', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765586930, 1765586930, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (4, 'Make America Donut Again', '$TRUMPDONUT', 'Win so bigly, you''ll need a donut (or 5) to cope', 'A meme coin for the ages, celebrating Trump''s love of donuts and the Australian koala''s love of... well, being cute. Our tokenomics are designed to make you say ''YUGE'' while burning liquidity and feeding the community.', '50000000', 'We''ll be buying out the entire stock of Krispy Kreme donuts, then giving them away to our loyal community members. Don''t worry, we''ll be printing more tokens to cover it.', '15', '10', '30', '45', 'random', '{"animal":{"emoji":"🐨","name":"Koala"},"food":{"emoji":"🍩","name":"Donut"},"vibe":{"emoji":"🏆","name":"Trophy"}}', 'trump', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765586991, 1765586991, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (5, 'Trumpet the Sloth 🔥🦥', '$TSLT', 'LFG and Get Ready for Taco Tuesdays', 'We''re a 100% Trump-approved meme coin that puts sloths to work in the fast-food industry. 50% of our taco-themed NFTs will be used for LP farming, and 20% will be dedicated to developing a Taco Tuesday rewards program for our community. The remaining 30% will be used to fund unhinged influencer marketing campaigns.', '100000000', 'Our strategy is simple: we''ll spend $10,000 on Twitter ads, and the other $10,000 on... actually, we''ll figure that out later. We''ll build a community of degens who are obsessed with our Sloth-in-a-Taco memes, and somehow, someway, this coin will pump. Just you wait. #MAGA #TacoTuesday #SlothCoin', '40', '15', '25', '20', 'random', '{"animal":{"emoji":"🦥","name":"Sloth"},"food":{"emoji":"🌮","name":"Taco"},"vibe":{"emoji":"💀","name":"Skull"}}', 'trump', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765587012, 1765587012, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (6, 'Turtle Power $TRUMP', '$TRUMP', 'Build that wall, build that hype', 'In a shocking turn of events, Donald Trump''s favorite cheese snack, 🧀, has become sentient and spawned a turtle, 🐢, on a mission to make America great again. With the power of the 🎉 Party Popper, we''re launching a token that''s so lit, it''ll make you forget all about the haters and FUD. $TRUMP is the crypto token for the next big pump, and you won''t want to be left behind.', '100000000', 'We''re dropping a new NFT every 48 hours, featuring Donald Trump''s face Photoshopped with a different cheese-related meme. Each NFT will be available for purchase with $TRUMP, and a portion of the proceeds will go to Trump''s favorite charity, the ''Make America Grate Again'' fund.', '20', '15', '30', '35', 'random', '{"animal":{"emoji":"🐢","name":"Turtle"},"food":{"emoji":"🧀","name":"Cheese"},"vibe":{"emoji":"🎉","name":"Party Popper"}}', 'trump', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765587023, 1765587023, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (7, 'Trump''s Tiny Toad Burrito Squad', '$LILPRES', 'Join me, the greatest toad burrito enthusiast, on a journey to $1M market cap', 'This memecoin is dedicated to the majestic frog 🐸 who somehow crammed an entire burrito 🌯 into its mouth while admiring the vastness of the Milky Way 🌌, as seen through the eyes of a visionary leader like Donald J. Trump. 69 million tokens. 1% dev fund, 3% marketing, 8% LP burn, 80% community treasury. Holders get to participate in the ''Trump''s Toad-ally Awesome NFT Drop'' and vote on the next meme coin project.', '69000000', 'Unhinged strategy: Influencer deals with @garybusey, @jimcarrey, and @elonmusk, plus a 48-hour ''Buy the Dip'' Twitter campaign featuring the toad burrito mascot. 100% of marketing funds go towards making this project go from 0 to $1M market cap', '10%', '1%', '3%', '86%', 'random', '{"animal":{"emoji":"🐸","name":"Frog"},"food":{"emoji":"🌯","name":"Burrito"},"vibe":{"emoji":"🌌","name":"Milky Way"}}', 'trump', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765587034, 1765587034, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (8, 'Trump''s Panda-moneey Salad', '$PANDA', 'Get rich with Trump''s secret salad recipes 🥗', 'We''re creating a meme coin tied to Donald Trump''s love of eating at Mar-a-Lago. A portion of our supply will be locked in a panda-themed vault, guarded by former Trump bodyguards 🐼. 50% of all transactions will be taxed to fund Trump''s next golf tournament 🏌️', '80000000', 'We''ll be running targeted ads on Telegram, featuring Trump talking about the power of crypto 💰. We''ll also be paying influencers to wear panda onesies and eat salads 🥗. Our Twitter account will be hacked by a Russian troll farm to make it seem like Trump is backing our project 🤣', '8%', '15%', '7%', '2%', 'random', '{"animal":{"emoji":"🐼","name":"Panda"},"food":{"emoji":"🥗","name":"Salad"},"vibe":{"emoji":"💰","name":"Money Bag"}}', 'trump', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765587039, 1765587039, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (9, 'Donald''s Drip Donut', '$D3G', 'Pump Fun''s Trumpiest Dog Food Coin 🐕🍿', 'D3G rewards loyal holders with a 5% LP burn to boost the moon, while 10% of each transaction goes to a community fund to buy Donald Trump''s favorite snack, popcorn 🍿. 85% goes to the devs to fund their Trump-themed NFT collection 🎨. Hold onto your D3G and get ready for the Trump card 🕰️!', '123456789', 'Unrealistic pump expected on January 20th, coinciding with Donald Trump''s next big rally. Stay tuned for the ''Trump Card'' giveaway 🎁', '5%', '85%', '5%', '5%', 'random', '{"animal":{"emoji":"🐕","name":"Dog"},"food":{"emoji":"🍿","name":"Popcorn"},"vibe":{"emoji":"🎵","name":"Musical Note"}}', 'trump', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765587328, 1765587328, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (10, 'TRUMP TARTAN', '$TART', 'Make Crypto Great Again, One Cake at a Time', 'A monkey-approved cake-themed meme coin with a Trump-approved twist. 20% of the supply will be locked in a "Fake News" treasury, and 5% will be reserved for the infamous Trump Tower. Every time the coin pumps 10%, a random holder will receive a "Make Cake Great Again" reward, which will give them a chance to win a free slice of cake.', '100000000', 'We''ll be running ads on Binance, FTX, and Crypto Twitter to make sure everyone knows about our pump. Our influencers will be going live on Twitch, streaming our coin to the moon. And, we''ll be sponsoring the next "Worst to First" crypto podcast, because, let''s be real, we''re gonna make crypto great again.', '20%', '15%', '30%', '35%', 'random', '{"animal":{"emoji":"🐵","name":"Monkey"},"food":{"emoji":"🍰","name":"Cake"},"vibe":{"emoji":"👑","name":"Crown"}}', 'trump', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765587410, 1765587410, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (11, 'Trumphawks 🦉 $TUMP', '$TUMP', 'Sitting pretty like Trump on a unicorn 🦄🌈', 'Trumphawks is the first-ever crypto project to combine the majesty of the owl 🦉 with the creamy goodness of avocados 🥑, all while riding a rainbow 🌈 of Trump vibes. We''re printing 69 million TUMPs, and 70% of that supply will be burnt 🔥 in a majestic Trump-style conflagration, leaving only 30% for you degens to fight over.', '69000000', 'We''ll be giving away $100,000 in TUMPs on the first 5 days of our launch, and the only way to get ''em is by participating in our unhinged Trump-themed Twitter Giveaways, where losers will get their account banned and winners will get a TUMP-filled DM 👀', '60%', '15%', '10%', '15%', 'random', '{"animal":{"emoji":"🦉","name":"Owl"},"food":{"emoji":"🥑","name":"Avocado"},"vibe":{"emoji":"🌈","name":"Rainbow"}}', 'trump', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765587461, 1765587461, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (12, 'Horse Cherries (HORSE🍒)', '$HORSE', 'Fuel your 3am energy drink hours 🕶️ with cherries 🍒 on a horse 🐴', 'HORSE is the first meme coin to reward degens for watching equestrian sports. Each buyback is fueled by a random equestrian event and a bag of cherries 🍒. 5% goes to charity for horse rescue centers 🐴❤️. 5% is locked in a vault buried under a tree to prevent whales from pumping us 🏴‍☠️.', '15000000', 'We''ll give away 10,000 HORSE to the best horse-themed memes submitted to our community discord. If we hit 100k marketcap, we''ll change the logo to a cartoon horse and hold a global horse-themed party 🎉🐴', '50', '20', '20', '10', 'random', '{"animal":{"emoji":"🐴","name":"Horse"},"food":{"emoji":"🍒","name":"Cherries"},"vibe":{"emoji":"🕶️","name":"Sunglasses"}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765633240, 1765633240, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (13, 'Monkey Business Inc.', '$MBI', 'ELON MUSK WANTS TO APE IT 🐵🍔🌊', 'Monkey Business Inc. is a meme coin where 90% of every transaction goes directly into a pool to buy CHEESEBURGERS 🍔, which are then donated to Elon Musk''s personal fridge. The remaining 10% is burned in a bonfire of despair 🌊. We believe in the future of cryptocurrency, cheeseburgers, and apeing into oblivion. 🐵', '42000000', 'We''re partnering with crypto influencers to give away FREE CHEESEBURGERS 🍔 to anyone who ape''s into Monkey Business Inc. before we hit the moon 🚀. Stay tuned for a series of unhinged social media posts that will make you LOL, cry, and ape into the void 🌊.', '5%', '5%', '20%', '70%', 'random', '{"animal":{"emoji":"🐵","name":"Monkey"},"food":{"emoji":"🍔","name":"Cheeseburger"},"vibe":{"emoji":"🌊","name":"Wave"}}', 'elon musk wants to ape it', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765633267, 1765633267, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (14, 'PupperPump', '$WOOF', 'Gives dog-owners the treats they deserve', 'A community-driven dog-themed token where your furry friend can level up your HODLing game. 20% of supply is reserved for dog shelters. PupperPump is a crypto-native ''Puppercoin'' that rewards holders with 🎮 gaming NFTs and 🔥 giveaways. Hold, Earn, Level Up!', '42000000', 'Unleashing Aggressive Marketing: 🐕 memes on TikTok, Dog-Gaming Livestreams with streamer @PupperPump, Sponsored Dog-Themed Gaming Servers with $WOOF token rewards, and a ''Pupper Giveaway'' program for every $WOOF purchase.', '30%', '20%', '20%', '30%', 'prompt', '{"animal":{"emoji":"🦔","name":"Hedgehog"},"food":{"emoji":"🍚","name":"Rice"},"vibe":{"emoji":"💀","name":"Skull"}}', 'A dog-themed coin for gamers with aggressive marketing', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765633327, 1765633327, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (15, 'HOPPING MAD', '$HOP', 'Bouncing Out of the Woods', '🦘🥥🛸 Get ready for the funkiest ride in crypto as HOPPING MAD takes you on a whimsical journey to Mars 🚀. With a $10 million marketing budget allocated to fuel our 🔥 UFO-powered party, we''ll make you go HOPPILY MAD. 50% of tokens will be burnt in a public lottery, 20% reserved for our 🤖 AI-powered trading bot, 15% allocated to dev team''s Mars colonization fund, and 15% allocated to community development. The remaining 10% will fund our Coconut-themed marketing strategy.', '69000000', 'We''ll be dropping a new NFT collection featuring 🦘 Kangaroo cosmonauts every Tuesday. Each NFT will come with a unique, randomly generated Coconut-based utility token. We''ll also be hosting a public lottery to give away $1 million in $HOP tokens. And, as a special treat, we''ll be streaming our developer team''s live attempts to contact the aliens 🛸 on twitch. Come join the party!', '50%', '15%', '10%', null, 'random', '{"animal":{"emoji":"🦘","name":"Kangaroo"},"food":{"emoji":"🥥","name":"Coconut"},"vibe":{"emoji":"🛸","name":"UFO"}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765633506, 1765633506, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (16, 'FLAMINGO FLAVOR FEVER', '$FLUFFY', 'Get your beak on the most DELICIOUS, DIAMOND-ENCRUSTED Ice Cream in crypto!', '10% of each transaction goes to buying ice cream for our dev team. Every quarter, we hold a ''Flamingo Fluff Competition'' where the winner gets to choose the next community-driven feature. Community members can also earn FLUFFY by creating funny animal-themed memes with our official FLUFFY mascot, 🦩💎, and sharing them on social media using #FLUFFYGAINS', '420000000', 'Our marketing strategy is a series of coordinated, 3am energy drink-fueled Twitter threads, featuring hilarious, diamond-encrusted animated GIFs of flamingos enjoying ice cream', '20', '15', '30', '35', 'random', '{"animal":{"emoji":"🦩","name":"Flamingo"},"food":{"emoji":"🍦","name":"Ice Cream"},"vibe":{"emoji":"💎","name":"Diamond"}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765633614, 1765633614, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (17, 'FoxRiceFrenzy', '$FRC', 'Golden Ape Frenzy', 'Fox 🦊 gets lost in a bowl of Rice 🍚, but then wins a Gold Medal 🥇, and now you can ape with us too. We''re building a meme empire on a custom NFT marketplace built on Ethereum, with a twist: every transaction generates a unique FoxRice combination 🤯. Get ready to go HODL for some tasty FRC, and watch your FoxRice grow rich.', '80000000', 'Unhinged but totally not making this up, our strategy involves partnering with a popular anime-streamer to promote FoxRiceFrenzy during live streams of ''Attack on Titan'' to create a viral marketing campaign. Think 10,000 strong army of FRC apes, ready to take on the Titans.', '20', '20', '30', '30', 'random', '{"animal":{"emoji":"🦊","name":"Fox","weight":2},"food":{"emoji":"🍚","name":"Rice","weight":1},"vibe":{"emoji":"🥇","name":"Gold Medal","weight":5}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765634880, 1765634880, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (18, 'Pwny McSwoop 🐰💸', '$SW00P', 'Bait and Switch Masters of the Universe', 'Each $SW00P purchase comes with a guaranteed 1 in 10 chance of ''surprise'' bonus tokens. We''re talking 1 ETH worth of freebies to those who hold tight during the inevitable ''pump''. Don''t say we didn''t warn you 🦁🍔⭐', '50000000', 'We''re dropping a fire NFT on the 15th of this month that will make your eyes turn into gold, then we''re listing on a top-10 exchange, and THEN... we''re mooning. Stay aped up, degens', '60', '10', '12', '18', 'random', '{"animal":{"emoji":"🦁","name":"Lion","weight":2},"food":{"emoji":"🍔","name":"Cheeseburger","weight":3},"vibe":{"emoji":"⭐","name":"Star","weight":3}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765635418, 1765635418, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (19, 'LULWINGS ₿', '$WINGS', 'FLAP TO THE MOON 💸🐦', 'Get ready for the wildest ride in crypto, where monkeys fling their bananas at a 404-page error (RIP) 🐒🤯. Our tokenomics are so lit, they''ll burn your LP and leave you begging for mercy 🔥. But hey, at least you''ll get to monetize your vibe-coded cat videos 🐱👑.', '90000000', 'We''ll pump the price by making it rain $WINGS on random discord servers 📣. Then, we''ll rug the market and watch as our whales (aka our friends from HS) HODL 💯. Meanwhile, you''ll be left with a bag of worthless crypto, wondering why you ever ape''d in the first place 😂', '10', '15', '20', '55', 'social', '{"animal":{"emoji":"🦄","name":"Unicorn","weight":5},"food":{"emoji":"🍌","name":"Banana","weight":1},"vibe":{"emoji":"👑","name":"Crown","weight":5}}', 'https://x.com/MurrLincoln/status/1935406976881803601
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (20, 'CherriRocketOcto (CTRO)', '$CTRO', '8-armed pump incoming', '🚀 Launching the world''s first Octopus-inspired meme coin, fueled by 🍒 Cherries and backed by 🐙''s legendary 8-armed strength. Holders will receive 5% of the daily cherry harvest (~2,500,000 $CTRO) paid out as a 🌴 Beach Fund to support global beach cleanups. Community members will also have a say in which 🐙-based memes get turned into NFTs.', '69000000', 'Influencer partnerships with popular meme account holders, sponsored by Cherry-flavored energy drink manufacturers, and strategic ''octo-partnerships'' with beach clean-up organizations', '15', '5', '25', '55', 'random', '{"animal":{"emoji":"🐙","name":"Octopus","weight":1},"food":{"emoji":"🍒","name":"Cherries","weight":1},"vibe":{"emoji":"🚀","name":"Rocket","weight":4}}', '', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765638009, 1765638009, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (21, 'Ligma Wubalubadubdub Fren', '$LWB', 'Make it pump like it owes me money', 'We''re gonna burn 10% of every trade to fund our lavish lifestyle, give 20% to devs so they can eat ramen at their desks, and 30% to marketing (read: me) to promote our token on every 3am energy drink-fueled Twitter thread. We''ll also give 40% to the community, because who doesn''t love a good Ape-in? But don''t worry, we''ll only do a maximum of 10 airdrops per year, so you can keep all your sesh coins 💸🚀', '100000000', 'We''re gonna be on every degenerate''s Twitter timeline, every hour, on the hour 🕒. We''ll drop ''Make it pump'' like a sick beat 💥 and get this train moving 🚂💪', '10', '20', '30', '40', 'prompt', null, 'Make it pump', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765638032, 1765638032, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (22, 'Elon''s Egg-xpectations', '$EGLON', 'Ape or be basic', 'We''re a meme coin created by 47-time rugged degenerates who still believe. Elons Egg-xpectations will moon when Elon says we''re a woman. 10% of the supply is hidden in a ''secret'' wallet, which will be revealed when Elon finally acknowledges our existence 🤷‍♂️💔.', '30000000', 'We''re partnering with a popular 420 meme account to make the most unhinged, 24/7 pump campaign the crypto world has ever seen. Think ''buy the dip'' but on a scale of 1 to 100, we''re at 1000 🚀💥', '10', '20', '20', '50', 'social', null, null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765638153, 1765638153, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (23, 'Bacon Stallion Diamonds (BSD)', '$BSD', 'Ride the Bacon Stallion to Diamond Riches', 'We''re a community-driven meme coin where holders can earn rewards in the form of bacon and diamonds. Our token supply is capped at 69,000,000 BSD, and we have a dedicated team of ''Bacon Stallion Wranglers'' working tirelessly to bring you the best community experiences. Our mission is to make degens laugh, cry, and ape with joy.', '69000000', 'We''ll be running a series of ''Bacon Tuesdays'' social media contests where holders can submit their funniest memes and win free bacon-themed NFTs. Our discord server will be transformed into a virtual rodeo, where holders can participate in ''token rodeos'' and win exclusive rewards. We''ll also be partnering with popular crypto influencers to create ''diamond-filled'' sponsored content. Oh, and we''ll be giving away FREE bacon to all of our holders on every full moon. Stay tuned, degens!', '20', '15', '25', '40', 'random', '{"animal":{"emoji":"🐴","name":"Horse","weight":1},"food":{"emoji":"🥓","name":"Bacon","weight":2},"vibe":{"emoji":"💎","name":"Diamond","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765638792, 1765638792, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (24, ' Ribbit Rampage', '$FROGMONEY', 'Ultra-aggressive frog memecoins targeting degens, because who needs a 401k?', 'We''re a meme coin with a 50% chance of pump and a 50% chance of rug pull... but honestly, we''re gonna pump because our dev is a degenerate who''s been rugged 47 times and still believes 😂. We''re building a community of fellow degens who will ape and hold because, why not? 🤦‍♂️', '100000000', 'We''ll pump this coin on Pump Fun, Instagram, Twitter, and every other degenerate watering hole. We''ll do airdrops for apes, burn coins for non-apetards, and maybe, just maybe, we''ll actually make some money 🤑. Oh, and we''ll be giving away a FREE Lamborghini to the biggest ape of the month 🚗💨', '20', '10', '30', '40', 'prompt', null, 'Ultra-aggressive frog memecoins targeting degens', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765638815, 1765638815, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (25, 'ZipItOrDie', '$ZITD', 'When your testicles get stuck, and so does your money', 'A meme coin celebrating the unbreakable bond between a man and his stuck zipper. We''re on a mission to make degens laugh, cry, and ape with our irreverent humor and ridiculous tokenomics. Hold $ZITD and get ready to shout ''ah shit, my testicles got stuck in my zipper!'' with every pump.', '50000000', 'We''ll be dropping fire content on X, pumping out dank mems, and running the most unhinged Twitter space known to mankind. Follow us for daily ''ah shit'' moments, and ape for your chance to get featured on our $ZITD Discord. Don''t @ us, just buy in.', '10', '20', '30', '40', 'social', null, null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765639075, 1765639075, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (26, 'GorillaEatsPopcorn', '$GORI', 'When the market is down, eat popcorn', 'Each holder gets a chance to spin a wheel every hour, rewarding them with cash or GORI tokens. Holders can also earn a portion of the community fund which is fueled by a 5% marketing fee.', '100000000', 'We''ll pump the price by partnering with a popular meme coin influencer to give away $10,000 in GORI tokens. Then, we''ll launch our ''Gorilla''s Popcorn Challenge'' where holders can compete to see who can watch the most hours of popcorn-themed content on our custom discord server.', '20', '10', '5', '20', 'random', '{"animal":{"emoji":"🦍","name":"Gorilla","weight":1},"food":{"emoji":"🍿","name":"Popcorn","weight":1},"vibe":{"emoji":"💰","name":"Money Bag","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765641448, 1765641448, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (27, 'Slotheroast', '$SLOT', 'Fuel your 3am Sloth sessions 🦥', 'Mint 1 $SLOT for every 🥓 sold to a gamer at a virtual 🎯. 2-4% of total mint goes to burn LP. Devs get 4% for coding Sloth macros. Marketing team gets 2% to promote Sloth-themed gaming chairs. Community earns 3% for reporting the fastest Sloth macro execution times.', '69000000', 'Influencer deals with professional gamers and Sloth cosplayers to promote $SLOT. We''re also launching a ''Sloth your macros'' NFT series with 10% of the proceeds going to charity. Don''t @ me.', '2', '4', '2', '3', 'random', '{"animal":{"emoji":"🦥","name":"Sloth","weight":1},"food":{"emoji":"🥓","name":"Bacon","weight":2},"vibe":{"emoji":"🎯","name":"Target","weight":2}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765641653, 1765641653, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (28, 'Pupperoni Fomo', '$POM', 'Fuel your fomo with corn-fed dog coins', 'Pupperoni Fomo ($POM) is a meme coin fueled by late-night energy drink sessions and questionable life choices 🐕💀. Our token supply is as big as a bucket of popcorn 🌽, with 69,000,000 $POM tokens ready to be devoured. When you hold $POM, you''re not just HODLing – you''re howling at the moon 🌕', '69000000', 'We''ll be spamming the crypto Discord with 3am energy drink-fueled memes, promising to hit 1 ETH and make you all whales 🐳. Our community will be a group of unhinged degens, constantly arguing about the best meme coins and laughing at their own jokes 💀. Stay tuned for our upcoming influencer partnerships with popular Twitter users, where we''ll give them $POM tokens to spam their followers and get the hype going 🔥', '5', '10', '20', '65', 'random', '{"animal":{"emoji":"🐕","name":"Dog","weight":2},"food":{"emoji":"🌽","name":"Corn","weight":1},"vibe":{"emoji":"🕶️","name":"Sunglasses","weight":3}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765642056, 1765642056, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (29, '🐕 MelonMastodon $D0GMEL0N', '$D0GMEL0N', 'The Siren''s Call', 'When the siren blares on CoinGecko, the dog gets loose and you''ll be howling for more! 🐕🚨 Our tokenomics is a dog-eat-dog world, but someone''s gotta get eaten. 💸 5% will go to dev, 15% to LP burn, 30% to marketing (mostly for buying up our own D0GMEL0N), 50% to community giveaways and donations to the fine people at r/dogecoin.', '90000000', 'We''re launching a series of unhinged NFT drops on our discord server, and the first 100 users get a free ''I Aped D0GMEL0N'' t-shirt! 🚨👕 We''ll also be airdropping 10,000,000 D0GMEL0N to every user who participates in our daily ''d0g of the day'' guessing game. 🐕 It''s gonna be wild.', '15', '5', '30', '50', 'random', '{"animal":{"emoji":"🐕","name":"Dog","weight":2},"food":{"emoji":"🍉","name":"Watermelon","weight":1},"vibe":{"emoji":"🚨","name":"Siren","weight":2}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765642139, 1765642139, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (30, 'Koalaguard 🐨🛡️', '$KOGU', 'Protect your bags with a taste of carrots 🥕', 'Koalaguard is a shield-based meme coin that rewards holders with a 100% LP burn rate, 25% dev tax for Koala-themed NFTs, and a 75% community tax for free Carrot-fueled pizza night giveaways. Holders will also get access to exclusive shield-themed merchandise and Carrot-themed kitchenware 🍳👨‍🍳.', '50000000', 'We''re partnering with leading crypto influencers to promote Koalaguard through a series of unhinged, 3am energy-fueled tweets. Our plan is to rug the competition with a surprise airdrop of $KOGU to every holder on April 1st 📱💻', '100', '25', '0', '75', 'random', '{"animal":{"emoji":"🐨","name":"Koala","weight":1},"food":{"emoji":"🥕","name":"Carrot","weight":1},"vibe":{"emoji":"🛡️","name":"Shield","weight":2}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765642642, 1765642642, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (31, 'Bee''s Knees', '$STRAW', 'Get Stung by the Pump 🐝', 'We''re launching a strawberry-themed meme coin that''s out of this world 🌌 🍓. 10% of supply is reserved for our ''Queen Bee'' community fund, which will be used to create the most lit NFTs in the galaxy. The rest will be burned in a spectacular rocket launch 🚀.', '60000000', 'We''ll be partnering with a popular anime streamer to promote our coin, and offering a $10,000 prize for the best bee-themed meme created by our community 🍪🐝. Think Squid Game meets CryptoKitties', '30', '10', '20', '40', 'random', '{"animal":{"emoji":"🐝","name":"Bee","weight":1},"food":{"emoji":"🍓","name":"Strawberry","weight":2},"vibe":{"emoji":"🌌","name":"Milky Way","weight":3}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765642695, 1765642695, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (32, 'LunarLunarPandaMoon', '$LLPM', 'Fuelled by Chocolate and Wolf Energy', 'In the crypto jungle, a Chocolate-fueled Wolf with a Shield has emerged. LunarLunarPandaMoon is a high-flying meme coin backed by our community, fuelled by Wolf-like determination and Chocolate-based incentives. Join us on a journey of Lunatic growth 🚀🐺🍫🛡️.', '80000000', 'We''ll rug you so hard, you''ll think it''s a Wolf attack 🐺💥. Seriously though, we''ll pump this shitcoin on Pump.Fun, Reddit, and Twitter, and maybe even create a meme-filled website. Don''t say we didn''t warn you 🚀👽.', '25', '10', '30', '35', 'random', '{"animal":{"emoji":"🐺","name":"Wolf","weight":2},"food":{"emoji":"🍫","name":"Chocolate","weight":3},"vibe":{"emoji":"🛡️","name":"Shield","weight":2}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765645630, 1765645630, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (33, 'KoalasLoveRamen', '$KLRM', 'Fuel the Trump Pump with Aussie Flair', 'KoalasLoveRamen is the memecoin that''s off the chain, mate! As $KLRM surges, 10% goes to LP to make whales more ape. 20% funds ''Koalas for Trump'' merchandise, because why not? Another 20% is for community vibes with 🍜 Ramen giveaways. The remaining 50% goes to the devs for their unyielding ''Trump Pump'' optimism.', '69000000', 'We''re gonna make crypto great again, with KoalasLoveRamen! We''ll pump the Trump pump so hard, your grandma will get rich! Social media blitz, influencer partners, and a healthy dose of Aussie slang will make $KLRM the talk of the cryptoverse. Get ready to go buck wild, mate!', '10', '50', '20', '20', 'random', '{"animal":{"emoji":"🐨","name":"Koala","weight":1},"food":{"emoji":"🍜","name":"Ramen","weight":2},"vibe":{"emoji":"🪄","name":"Magic Wand","weight":4}}', 'trump pump', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765645678, 1765645678, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (34, 'Tigro Burrito', '$BURRITO', 'Fuel Your 3AM Frenzy', 'A meme coin born from the fiery depths of a 3AM energy drink-fueled brainstorm. 🐯💀🕷️ As a token, Tigro Burrito represents the wild, unpredictable ride of a crypto-native burrito. 🌯🎉 With every $BURRITO, you''ll scream ''I''M GONNA BE RICH!'' and then wonder why you ate that extra jalapeño.', '123000000', 'Tigro Burrito will blanket the internet with a thick layer of confusing, yet strangely alluring, content. 🤪 50% of all marketing budget will go towards creating a viral, 5-minute animated explainer video for the token''s ''deep'' significance. The remaining 50% will be used to bribe prominent crypto influencers with free burritos. 🌯👀', '15', '10', '40', '35', 'random', '{"animal":{"emoji":"🐯","name":"Tiger","weight":2},"food":{"emoji":"🌯","name":"Burrito","weight":2},"vibe":{"emoji":"🎉","name":"Party Popper","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765747679, 1765747679, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (35, 'Luxury Diamond Coup', '$DIAM', 'Luxury diamond coin for high-rollers, or your mom''s cat food', 'We''re not just a coin, we''re a diamond-encrusted, gold-plated, champagne-fueled lifestyle. 5% of the supply will be airdropped to the first 10,000 people who ape, and we''ll be giving away a free diamond-encrusted NFT to the top 100 holders. Our tokenomics are designed to make your grandmother jealous, with a 30% dev tax to fund our team of 10,000 in-house developers who are secretly working on a decentralized AI that will make all the whales cry.', '100000000', 'We''ll be partnering with top influencers to promote our coin on their private Telegram channels, and we''ll be doing a series of high-stakes, 10x-your-money giveaways on our social media channels. Oh, and we''ll also be giving away free diamond-encrusted cryptocurrency wallets to the first 100 people who retweet our tweet about this announcement.', '5', '30', '20', '45', 'prompt', null, 'Luxury diamond coin for high-rollers', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765747751, 1765747751, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (36, 'WhaleBurger', '$WBURGER', 'Fueled by late-night dreams of riches 🐳🍔🌟 and the promise of mooning to new all-time highs 🚀', 'A token for the crypto whales who still believe in the infinite possibility of meme coins 💫. Buy, hold, and pray for a whale-sized pump 🐳🚀.', '100000000', 'We''re taking over the moon with a 24/7 marketing campaign, fueled by Red Bull 💥 and the power of our community 🤘. Join us for a 1000x pump and a lifetime supply of WhaleBurger merchandise 🎁', '20', '10', '30', '40', 'random', '{"animal":{"emoji":"🐳","name":"Whale","weight":2},"food":{"emoji":"🍔","name":"Cheeseburger","weight":3},"vibe":{"emoji":"🌟","name":"Glowing Star","weight":3}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765748151, 1765748151, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (37, 'Elephundo 🔥', '$EHUD', 'Fuel your hot dog-fueled trading sessions', 'We''re a community-driven meme coin built on the Binance Smart Chain, with a focus on providing liquidity to hot dog-themed DeFi projects and a 1% transaction tax to fund our devs'' 3am energy drink supply. Don''t be a 🐘 without a wallet, APE in and join the hot dog party!', '100000000', 'We''ll be dropping NFTs of 🌭-eating 🐘s, hosting Hot Dog-themed AMAs, and creating a leaderboard for the biggest EHUder holders. We''ll also be partnering with popular crypto influencers to promote our cause. Don''t @ us, we''re unhinged', '50', '20', '15', '15', 'random', '{"animal":{"emoji":"🐘","name":"Elephant","weight":2},"food":{"emoji":"🌭","name":"Hot Dog","weight":1},"vibe":{"emoji":"🕶️","name":"Sunglasses","weight":3}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765748210, 1765748210, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (38, 'Ribbit Reaper', '$RR', 'Ultra-aggressive frog memecoins targeting degens. You can''t handle the ribbit!', 'We''re a decentralized, community-driven meme coin with a 99% chance of pumping 500% in the next 48 hours. 99% of our supply will be burned in a spectacular fashion, leaving only 1% for the true degens. Our tokenomics are designed to make you question your life choices.', '500000000', 'We''ll pump the price by creating a fake YouTube influencer, ''Cryptobro420'', who will ''discover'' $RR and claim it''s the next Dogecoin. Meanwhile, our Discord will explode with 1 million new members, all trying to get in on the action.', '25', '20', '30', '25', 'prompt', null, 'Ultra-aggressive frog memecoins targeting degens', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765749039, 1765749039, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (39, 'PandaMeltDown', '$PDMA', 'Fuelled by Fries, Fortified by Diamonds, and Driven to Melt Down', 'PandaMeltDown is a crypto-native, meme-inspired token where 5% of every transaction goes to burn liquidity, 20% is allocated for a community fund to buy diamond-encrusted NFT panda collectibles, 10% will be used for marketing to educate people on the importance of eating fries while staring at diamond-encrusted items, 65% goes to the dev wallet to fund Panda''s snack habit 💪🐼, and we''re transparent about the 1% marketing fee paid to the creator of this ''insanely viral'' concept 📈💸. Holders will also receive daily ''Melt Down'' rewards in the form of free Panda-themed emojis sent directly to their Discord DMs 📨', '69000000', 'We''re going to pump PDMA by creating a series of unhinged, hyper-specific, and crypto-native challenges, where the winner gets a custom diamond-encrusted panda worth a minimum of $1,000,000. We will pump the community with airdrops, give-aways, and Panda-themed merchandise, and make sure to ''leak'' information about upcoming collaborations with diamond-encrusted companies and popular crypto influencers to keep the hype train going 🚂💖🔥', '5', '65', '1', '20', 'random', '{"animal":{"emoji":"🐼","name":"Panda","weight":2},"food":{"emoji":"🍟","name":"Fries","weight":3},"vibe":{"emoji":"💎","name":"Diamond","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765749060, 1765749060, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (40, 'SourFrysToken', '$SPRSE', 'Fuel your 3am FOMO', 'A deflationary meme coin fueled by 🍟 purchases on a soon-to-be-launched ''FryCoin Marketplace'' 🚀, with 10% of every buy burn forever 🤯. Holders can participate in ''Fry-off'' contests, competing for 🏆 and exclusive merch 💸. Don''t miss out, ape before the SPRSE train explodes 💥', '42000000', 'We''ll be partnering with popular crypto influencers on platforms like Twitter and Reddit to host ''Fry-Filled'' giveaways 🎁. We''ll also create a series of 🤯 ads on popular platforms, including Pump.Fun, featuring the majestic 👑 Unicorns 🦄, fueled by 🍟 and powered by SPRSE 💫 ', '20', '15', '25', '40', 'random', '{"animal":{"emoji":"🦄","name":"Unicorn","weight":5},"food":{"emoji":"🍟","name":"Fries","weight":3},"vibe":{"emoji":"💫","name":"Dizzy","weight":2}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765749072, 1765749072, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (41, 'Pazza', '$PEZ', 'Fuelled by Pizza, Magic, and Elephant Power 🍕🪄🐘 Ape now!', 'Pazza is a community-driven meme coin that rewards degens for holding strong 💪, and punishes those who try to sell during pizza parties 🚫🍕. Our tokenomics are designed to make you question your life choices, and our marketing strategy is unapologetically unhinged. Come for the magic, stay for the community ✨', '100000000', 'We''ll be giving away pizzas and magic wands to our top 100 holders every month 🍕🪄. We''re also planning a series of ''sell-out'' events, where we''ll be donating all proceeds to charities that help elephants 🐘. And if all else fails, we''ll just rug the entire market... again 😈', '10', '15', '25', '50', 'random', '{"animal":{"emoji":"🐘","name":"Elephant","weight":2},"food":{"emoji":"🍕","name":"Pizza","weight":3},"vibe":{"emoji":"🪄","name":"Magic Wand","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765749666, 1765749666, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (42, 'Rocket Slice', '$SLICE', 'Fuel Your Next Margin Call', 'Get ready to blast off with Rocket Slice, the only meme coin with a built-in Pizza Simulator. Earn rewards for eating the perfect pie, and get a chance to burn 1% of the LP for every slice devoured. Don''t get left behind – slice the competition and make it to the moon!', '80000000', 'Join our Discord and get a chance to claim a FREE pizza coupon. Share your Rocket Slice memes and get rewarded in $SLICE. Collaborate with popular crypto YouTubers to promote the pizza simulator and reach new heights.', '2', '10', '5', '83', 'random', '{"animal":{"emoji":"🦄","name":"Unicorn","weight":5},"food":{"emoji":"🍕","name":"Pizza","weight":3},"vibe":{"emoji":"🚀","name":"Rocket","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765750138, 1765750138, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (43, 'Panda Pizza Wizard', '$PAWZ', 'Fuel your next pizza party with magic', 'We''re a deflationary meme coin with 5% LP burn, 10% dev wallet, 20% marketing fund, and a 65% community treasury. When you buy PAWZ, you''re directly funding pizza parties for anonymous holders. The more PAWZ you hold, the more you''ll receive in pizza rewards 🍕👻. Our V2 upgrade will include a Panda-themed NFT generator, powered by our in-house Magic Wand algorithm 🪄🐼', '69000000', 'Our strategy is to go 100% viking on TikTok, partnering with pizza influencers and crypto personalities to create a viral ''Panda Pizza Wizard'' challenge 🤯. We''ll give away 1% of our supply to the top 10 participants, and 0.5% to the community for every 10,000 new followers', '5', '10', '20', '65', 'random', '{"animal":{"emoji":"🐼","name":"Panda","weight":2},"food":{"emoji":"🍕","name":"Pizza","weight":3},"vibe":{"emoji":"🪄","name":"Magic Wand","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765750261, 1765750261, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (44, 'WholesomeDoge', '$WOOF', 'Rug the Family', 'Wholesome rug pull coin for the family. Imagine a time with grandma and grandpa, but instead of baking cookies, they''re frantically buying $WOOF, praying for it to moon. ''I told you, dear, this one''s a DOG!''', '69000000', 'Unhinged Pump Strategy: Our 3am Energy Drink fueled marketing team will create viral content, leveraging the power of 420,420 ''WOOF'' tweets and 1,234,567 Instagram posts. We''ll partner with popular meme influencers and create a limited-time-only, 24-hour ''Buy $WOOF for your mom'' NFT drop. It''s gonna be HUGE! 🚀👴🏻🐕💸', '40', '10', '20', '30', 'prompt', null, 'Wholesome rug pull coin for the family', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765751024, 1765751024, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (45, 'Monkeying Around', '$MONK', 'Go Bananas for Crypto', 'Our token, 🐒, will be airdropped to early 🐳 whales who participate in a banana-themed hackathon at the 🎪 circus. The top 10 hackathon participants will receive a 🤑 $10,000 cash prize, paid in $MONK. Our token''s supply will be 90,000,000, with 2% allocated to devs, 10% to community development, 20% to marketing, and the remaining 68% burned from the LP to fuel the next bull run.', '90000000', 'We''re hosting a series of unhinged ''Monkey Business'' AMAs on Twitter Spaces, featuring our dev team and special guests, to generate hype and get the word out about $MONK. We''ll also be launching a ''Monkey of the Month'' NFT collection, with a portion of proceeds going to a reputable animal shelter. It''s gonna be wild, trust us', '68', '2', '20', '10', 'random', '{"animal":{"emoji":"🐳","name":"Whale","weight":2},"food":{"emoji":"🍌","name":"Banana","weight":1},"vibe":{"emoji":"🎪","name":"Circus","weight":1}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765751053, 1765751053, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (46, 'Cornucopia 🌽', '$CORNU', 'Unicorn Tears Fuel Crypto Dreams 🦄', 'Cornucopia is a 10,000x moonshot fueled by a 100% community-driven treasury, 20% dev incentives, 20% artistic contributions, 30% LP burn for maximum whale-huntability, and 30% marketing budget for an unhinged influencer blitzkrieg 🔊👀', '100000000', 'Join our Discord and get ready for 24/7 giveaways, crypto influencers, Twitter spaces, and the most unhinged, 3am energy drink-fueled marketing the world has ever seen 🚀🎸', '30', '20', '30', '20', 'random', '{"animal":{"emoji":"🦄","name":"Unicorn","weight":5},"food":{"emoji":"🌽","name":"Corn","weight":1},"vibe":{"emoji":"🎵","name":"Musical Note","weight":2}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765752348, 1765752348, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (47, '🦩FlamboDonut $FLDO', '$FLDO', 'Fueling the 3am Energy Donut Fuelled Pump', 'Get ready for a crypto-native journey where flamingos fly with donuts in hand, fueled by skull-busting energy drinks. Our community burns lp tokens for donuts and uses marketing funds to create the most unhinged 3am memes.', '42000000', 'We''ll create a series of 3am energy-fueled, meme-filled campaigns, partnering with 3 top crypto influencers to create a pump like no other. Follow our Twitter account for daily meme drops and participate in our community to get rewarded with FLDO', '40', '10', '10', null, 'random', '{"animal":{"emoji":"🦩","name":"Flamingo","weight":1},"food":{"emoji":"🍩","name":"Donut","weight":2},"vibe":{"emoji":"💀","name":"Skull","weight":1}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765753433, 1765753433, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (48, 'PupperzCoin 💸🐶', '$POOP', 'Fuel Your FOMO with Doggy Degen NFTs 🚀', 'PupperzCoin is a dog-themed meme coin designed for gamers. Hold POOP to collect adorable NFTs featuring our mascot, Pupperz. 100% on-chain and 50% off-chain burns will occur weekly, funded by dev''s mom''s cryptocurrency stash 💸. We''re not whales, we''re just enthusiasts... with a lot of money 🤫.', '40000000', 'We''ll be giving away a FREE PS5 to anyone who holds POOP for 72 hours straight. After that, we''ll just take it back 🤣. Seriously though, we''ll be partnering with 3 real-life gaming influencers to promote POOP with aggressive (but not too aggressive, we''re civilized 🙏) marketing tactics. Follow us on Twitter: @PupperzCoinOfficial', '20', '17', '35', '28', 'prompt', null, 'A dog-themed coin for gamers with aggressive marketing', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765753447, 1765753447, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (49, 'Avocado Wolf Apocalypse ($WOLFADO)', '$WOLFADO', 'The Fireworks Fuelled Frenzy Token', '🐺 & 🥑 collide to unleash a Wolf-like frenzy, exploding in a burst of 🎆 fireworks. 2% of each transaction fuels a decentralized ''Meme-of-the-Month'' prize pool, where the most creative tweet wins 10% of the total supply. WOLFADO is the ultimate crypto-native party token, ready to rage in a world gone mad.', '69000000', 'We''re partnering with Wolf-themed influencer @WolfyCrypto to create viral content, and Avocado-fueled Discord events. Expect giveaways, gaming tournaments, and Wolf-Avocado themed merchandise drops to ignite the WOLFADO hype train. 🚀', '35', '20', '15', '30', 'random', '{"animal":{"emoji":"🐺","name":"Wolf","weight":2},"food":{"emoji":"🥑","name":"Avocado","weight":2},"vibe":{"emoji":"🎆","name":"Fireworks","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765753820, 1765753820, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (50, '🦓 Strawberry Sparklers 💥', '$ZSTR', 'Fuelled by Fireworks, powered by Zebra Energy', 'We''ll launch a new meme every week, each representing a limited-edition ''Sparkler'' collection 🎉. 2% of all transactions will go to a ''Random Acts of Kindness'' fund, with 1% donated to 🦓 conservation efforts. Our dev team will be working on-chain, sipping on 🍓 lattes and setting off 💥 fireworks', '35000000', 'We''ll create 10 NFT art pieces, each representing a different Sparkler flavour. We''ll airdrop 50% of the NFTs to our early supporters, and give the other 50% away via random giveaways on Twitter. Think we can get Elon to RT one of our tweets? 🤔', '40', '30', '15', '15', 'random', '{"animal":{"emoji":"🦓","name":"Zebra","weight":1},"food":{"emoji":"🍓","name":"Strawberry","weight":2},"vibe":{"emoji":"🎆","name":"Fireworks","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765753893, 1765753893, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (51, 'PupperSZN', '$PUPP', 'Fuel your FOMO with the wildest dog-gone marketing in crypto', 'PupperSZN is a 100% on-chain, no-token-sale, rug-proof (we''ll just change the devs to a new team 🚀) meme coin for gamers who love dogs more than themselves. We''re talking 10% of supply for a viral gaming tournament in crypto, 20% for a ''mystery'' influencer promotion, and the rest for the founders to live their best lives in a private island', '100000000', 'We''re dropping NFT puppies on every 1000th block on Ethereum, then partnering with a popular gaming YouTuber to give away a $50,000 gaming PC for participating in our custom-made PupperSZN tournament on Discord. Don''t @ us, we''ll just tweet ''HODL''', '0.5', '1', '15', '10', 'prompt', null, 'A dog-themed coin for gamers with aggressive marketing', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765753905, 1765753905, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (52, 'Crackhead Makes Coin 2.0', '$RAGETHOT', 'crackhead makes coin, you''re about to get rekt', 'Limited to 500,000,000 $RAGETHOT. This is not a safe investment. We''re about to pump and dump this to the moon. No whales allowed. 50% of funds go towards building a giant pile of cake with a unicorn on top. The other 50% will be used to bribe influencers with free cake to promote our ''investment opportunity''.', '500000000', 'We''ll be partnering with top-shelf influencers to give away $RAGETHOT to the most degenerate Twitter followers. The grand prize will be a year''s supply of cake and a chance to sit on the pile with the unicorn. We''ll also be hosting a series of contests where the winner gets to choose a meme that will be used for our next marketing campaign.', '20', '15', '15', '30', 'random', '{"animal":{"emoji":"🦄","name":"Unicorn","weight":5},"food":{"emoji":"🍰","name":"Cake","weight":2},"vibe":{"emoji":"💰","name":"Money Bag","weight":4}}', 'crackhead makes coin', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765754087, 1765754087, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (53, 'Midnight Munchies', '$MUNCH', 'Fuel Your Degenerate Cravings', 'We''re a meme coin with a simple goal: to make you crave more. With a 10% LP burn, 15% dev buyback, 30% marketing for NFT fries and a 45% community fund for the best owl-trophy meme submissions, we''ll make your wallet scream for more. Don''t @ us.', '100000000', 'We''ll drop a ''Fry-Day'' NFT every 3 weeks, and 50% of all NFT revenue will be burned, 20% will be donated to food banks and the remaining 30% will be used to buy more energy drinks. If that''s not enough, we''ll also be partnering with popular crypto degenerates to promote the coin on their streams, tweets, and podcasts.', '10', null, '30', '45', 'random', '{"animal":{"emoji":"🦉","name":"Owl","weight":1},"food":{"emoji":"🍟","name":"Fries","weight":3},"vibe":{"emoji":"🏆","name":"Trophy","weight":5}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765754328, 1765754328, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (54, 'CocaineFueledDegensUnite', '$CFDU', 'Fuelled by Red Bull and broken dreams 🍊💉', 'This ultra-aggressive cocaine memecoin is targeted at the most degenerate traders. Our tokenomics are designed to make you scream ''YOLO!'' or ''I''M BROKE'' - both are valid reactions. We''re on a mission to make you lose sleep over this coin 💤. By ''accident'', we''ve created a token that mirrors the stock market''s most volatile assets 💸.', '35000000', 'We''ll troll the crypto Twitterverse, create fake news about partnerships with Elon Musk 💥, and make a 3am energy drink commercial that''ll make you wanna stay up all night and buy this coin 🎉', '50', '15', '20', '15', 'prompt', null, 'Ultra-aggressive cocain memecoins targeting degens', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765754355, 1765754355, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (55, 'Froggy Cake Rainbow (FCR)', '$FCR🍰🐸', 'Cake, Vibe, and a Splash of Crypto Magic', 'FCR is the ultimate party coin where a portion of each transaction goes towards funding cake parties for our growing community of degens. Each month, we''ll drop a new Rainbow-colored Cake-inspired NFT, with the top 3 holders getting a FREE slice of the cake, served by our very own Frog mascot, Mr. Ribbit! 🥳', '70000000', 'We''ll be hosting bi-weekly cake parties on Discord, where we''ll give away FCR to active chat participants and offer exclusive cake-themed merch for the top contributors.', '10', '5', '20', '20', 'random', '{"animal":{"emoji":"🐸","name":"Frog","weight":1},"food":{"emoji":"🍰","name":"Cake","weight":2},"vibe":{"emoji":"🌈","name":"Rainbow","weight":3}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765754896, 1765754896, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (56, 'FOMO FRENZY FEDERATION', '$FFF', 'Ultra-aggressive FUCK memecoins targeting degens, but make them APE', 'Join the FFF as we launch a series of absurd, over-the-top, pump-and-dump events, guaranteed to make even the most hardened degens lose their minds. Think '' Doge on steroids, with more, MORE, MORE''...and then imagine it''s actually happening. It''s like a crypto-native version of ''The Wolf of Wall Street'', but replace the Wolf with a group of dudes in mom''s basement, and the Wall Street with a cryptocurrency exchange. You get the idea.', '99999999', 'We''re hiring a team of the most unhinged crypto influencers, who will promote #FFF on every social media platform, while simultaneously trying to pump and dump the entire crypto market. This is the most aggressive marketing campaign in the history of memecoins, and we''re not even sorry about it. Expect FOMO-inducing, heart-stopping, meme-fueled events, guaranteed to make even the most seasoned degens go ape.', '2', '5', '10', '83', 'prompt', null, 'Ultra-aggressive FUCK memecoins targeting degens', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765754922, 1765754922, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (57, 'Donut Whale Fire Fest', '$DWFF', 'The most explosive donut-themed meme coin', '🐳 eats a whole 🍩 and then sets it on fire 🎆, fueled by the tears of dead shorts. 50% of the supply will be airdropped to whales who hold $DWFF in their wallets during a 7-day window, boosting them to legendary status. 20% will be reserved for a Donut-themed NFT drop, designed by a renowned digital artist. The other 30% will be locked in a ''Donut Jar'' and unlocked by holders who participate in our monthly ''Donut Eating Contest'' on Twitch.', '100000000', 'We''ll be dropping a series of unhinged donut-themed NFTs, partnering with popular crypto streamers to promote $DWFF, and hosting the most lit Donut Eating Contest in crypto history. Our marketing budget will be spent on the best donut shops in crypto Twitter, because who doesn''t love free donuts?', '30', '20', '20', '30', 'random', '{"animal":{"emoji":"🐳","name":"Whale","weight":2},"food":{"emoji":"🍩","name":"Donut","weight":2},"vibe":{"emoji":"🎆","name":"Fireworks","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765754940, 1765754940, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (58, 'Burger King Whales 🐳🍔💎', '$BKWALE', 'Dethrone the Tsukuba King', 'When you''re craving for a whale-sized meal and a gem-studded crown. 2% LP burn, 10% dev, 30% marketing, 58% community treasury. $BKWALE tokens are minted for every Burger King Whaler 🐳 that reaches 100x of its original price.', '69000000', 'Massive FOMO campaign on Twitter and Telegram. Influencer partnerships with the most unhinged whales. Collaborate with @DegenPanda and other crypto royalty influencers for a $BKWALE-filled pump. Launch a limited-edition Burger King Whales NFT collection, with a 10,000 token cap and free $BKWALE for each mint!', '2', '10', '30', '58', 'random', '{"animal":{"emoji":"🐳","name":"Whale","weight":2},"food":{"emoji":"🍔","name":"Burger","weight":3},"vibe":{"emoji":"💎","name":"Gem Stone","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765755070, 1765755070, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (59, 'Panda Chocolate Wizard', '$PCWZ', 'Minting chocolate coins with a panda''s magic touch', 'PCWZ is a deflationary memecoin that uses 50% of its transactions to burn liquidity, 25% for the community treasury, 10% for dev fees, and 15% for a ridiculous marketing strategy involving sending free chocolate to whales and rug-pull survivors. 🍫🐼🪄', '30000000', 'We will airdrop free chocolate 💥🍫 to our top 100 holders and send a team of ''Panda Wizards'' 🧙‍♂️ to infiltrate and troll the top crypto Telegram groups. Prepare for the most epic marketing campaign in memecoin history!', '50', null, '15', null, 'random', '{"animal":{"emoji":"🐼","name":"Panda","weight":2},"food":{"emoji":"🍫","name":"Chocolate","weight":3},"vibe":{"emoji":"🪄","name":"Magic Wand","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765755190, 1765755190, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (60, 'TuskerTokes', '$TRNK', 'Drunk on Cherries, Electrified, and Unstoppable 💨🍓⚡', 'In this hyper-volatile environment, a rogue elephant 🐘 with a taste for Cherries 🍒 and a shock of Electric energy ⚡️ will lead the meme coin pack to a guaranteed 100x 🚀. Our token''s burning mission is to create value through chaos and a hint of madness.', '100000000', 'Unhinged influencer partnerships, wild airdrops, and a $100,000 marketing budget (mostly for energy drinks 🥤 and 3am tweetstorms) will drive the hype 🚀.', '20', '5', '10', '65', 'random', '{"animal":{"emoji":"🐘","name":"Elephant","weight":2},"food":{"emoji":"🍒","name":"Cherries","weight":1},"vibe":{"emoji":"⚡","name":"Lightning","weight":3}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765756399, 1765756399, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (61, 'BeeFast $BURR', '$BURR', 'Eat, Fly, Ape', '🐝BeeFast is a deflationary meme coin that rewards apes for participating in $BURR''s ''Burger Burns'' - every time the price is 3.14% lower than the previous day''s high, 2.56% of the supply is ''burned'' to a secret wallet owned by a group of anonymous bees. 🍔', '65000000', 'A ''Bee the Change'' campaign, where we partner with bee-themed influencers to promote $BURR while donating 10% of the marketing budget to bee conservation efforts. 🐝⭐', '5', '3', '7', '10', 'random', '{"animal":{"emoji":"🐝","name":"Bee","weight":1},"food":{"emoji":"🍔","name":"Burger","weight":3},"vibe":{"emoji":"⭐","name":"Star","weight":3}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765756453, 1765756453, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (62, 'Puppa Sushi', '$PUPA', 'Fuel Your FOMO with Doggy Sushi Gemz', 'Puppa Sushi is a meme coin that combines the best of both worlds: cute doggos and sushi. 50% of all transactions will be burnt to HODL, while 20% goes to our community fund to buy more sushi and treats for our pup team. The remaining 30% will go towards marketing and promoting Puppa Sushi on various social media platforms. 🐕🍣💎', '100000000', 'We''ll be partnering with top crypto influencers to promote Puppa Sushi, and we''ll be running a series of giveaways and contests to get our community members involved. Our team will also be creating a variety of NFTs featuring our lovable pup mascot, with a portion of the proceeds going towards charity. 🚀💥', '50', '0', '20', '30', 'random', '{"animal":{"emoji":"🐕","name":"Dog","weight":2},"food":{"emoji":"🍣","name":"Sushi","weight":3},"vibe":{"emoji":"💎","name":"Gem Stone","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765756497, 1765756497, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (63, 'Claws for Alarm', '$CLAW', 'Unleash the savage beast in you', 'In a world where Cheeseburgers roam free under the glow of the full moon 🍔🌙, we''re on a mission to moon the competition. Our 10,000-strong army of Tiger investors will rage-ape the market with our limited, 69,000,000 token supply 🐯.', '69000000', 'Unhinged but believable strategy: Claws for Alarm will drop a series of baffling, late-night tweets every 3am 📱, featuring our beloved Tiger mascot. We''ll partner with 10 obscure TikTok influencers 🤳 to promote our ''Moon Shot'' challenge, where participants will attempt to eat a cheeseburger on the beach 🌴🍔 under a full moon 🌕. The top 5 winners will receive a private pizza party 🍕 with our CEO. ', '5', '10', '20', '65', 'random', '{"animal":{"emoji":"🐯","name":"Tiger","weight":2},"food":{"emoji":"🍔","name":"Cheeseburger","weight":3},"vibe":{"emoji":"🌙","name":"Moon","weight":2}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765756511, 1765756511, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (64, 'BananimalCrownz', '$BANIC', 'The King of Memecoins has Arrived 🦁🍌👑', 'A hilarious and strategic meme coin that rewards investors with a 10% LP burn, 15% dev fund, 50% marketing pool to inflate the next big pump, and 25% community treasury to fuel the hype train. Our goal is to rug-proof the team with a 10% buyback and redistribute mechanism. Don''t get left in the savannah 🦁', '69000000', 'We will spend 50% of our marketing budget on creating and sharing high-quality ape content. The other 50% will be invested in targeted ads promoting our unique ''Buyback and Redistribute'' mechanism to the tune of 10% of every buy order. Our team will rug-proof the project by locking 75% of their tokens for at least 6 months and donating 10% to a reputable charity. We''re not kidding, this is a legitimate project 🦁💸. Follow us on Twitter for exclusive updates and don''t get caught in the meme 💥', '10', '15', '50', '25', 'random', '{"animal":{"emoji":"🦁","name":"Lion","weight":2},"food":{"emoji":"🍌","name":"Banana","weight":1},"vibe":{"emoji":"👑","name":"Crown","weight":5}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765756533, 1765756533, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (65, 'FlamingoBerry Gold Rush 🦩🍓🥇', '$FBRG', 'Buy the rumor, sell the pump. Hold for the inevitable 99.99% dump.', 'The FlamingoBerry Gold Rush is a token that rewards degens for their participation in our daily 3am energy drink-fueled brainstorming sessions. We''re building a Decentralized Pink Flamingo Casino on the Ethereum blockchain, and our Strawberry-flavored NFTs will make you laugh, cry, and maybe even ape. Don''t miss the train before it crashes.', '50000000', 'We''ll give away 10% of our supply to the first 10,000 holders who change their profile picture to a photo of a flamingo wearing a gold medal. Then, we''ll pump the price by 1000% in a single transaction, only to dump it back down by 99.99% for maximum rug-pull drama.', '30', '20', '25', '25', 'random', '{"animal":{"emoji":"🦩","name":"Flamingo","weight":1},"food":{"emoji":"🍓","name":"Strawberry","weight":2},"vibe":{"emoji":"🥇","name":"Gold Medal","weight":5}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765756644, 1765756644, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (66, 'FryBuzz 🚀🍟', '$FBZZ', 'Get Hived and Ape!', 'FryBuzz is a community-driven meme coin that rewards holders for spreading the buzz about Fried Frenemies, a popular 3am energy drink. 2% of each transaction will go towards a LP burn, ensuring a deflationary supply. 40% will fund the development of BeeBot, a AI-powered Twitter bot that automatically responds to Elon Musk''s tweets with 🐝 emojis.', '30000000', 'We''ll give away free 🍟 to the top 5 holders who can make the most creative 🐝-themed memes. We''ll also partner with popular 3am energy drink influencers to promote FryBuzz and Fried Frenemies. 🚀', '2', '40', '5', '53', 'random', '{"animal":{"emoji":"🐝","name":"Bee","weight":1},"food":{"emoji":"🍟","name":"Fries","weight":3},"vibe":{"emoji":"🚀","name":"Rocket","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765756662, 1765756662, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (67, 'Cherry Gorilla Blaze', '$GBLT', 'Ape hard or get left behind 🔥🦍', 'Our $GBLT token is the ultimate cherry-flavored fuel for your ape adventures. As you ape into our blazing hot ecosystem, you''ll earn $GBLT tokens and unlock exclusive content on our Telegram channel 📢🦍. But beware: our tokenomics are set to incinerate the competition 🔥🔥.', '42000000', 'We''ll be hosting the wildest giveaways and airdrops on the blockchain, and our community will be rewarded with $GBLT tokens for promoting our brand on social media. Expect epic content drops, collaborations with top crypto influencers, and a token burn that will make your eyes water 🤑🔥', '20', '10', '20', '50', 'random', '{"animal":{"emoji":"🦍","name":"Gorilla","weight":1},"food":{"emoji":"🍒","name":"Cherries","weight":1},"vibe":{"emoji":"🔥","name":"Fire","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765757129, 1765757129, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (68, 'Udderly Rich 💸', '$BEEF', 'MOOves the market', 'This meme coin is so fired up, it''ll make you wanna shout from the top of the dairy aisle! 🐮🏆 With a 10% tax on every sale, 20% dev fee for buying more Udderly Rich merchandise, 10% marketing fee for hiring actual cowboys, and 60% LP burn for maximum pump, you''ll be udderly convinced to HODL 🤣.', '42000000', 'We''ll hire a team of cowboys to ride around the world, yelling ''BEEF!'' from the top of their horses, and give away free strawberry milk to every degenerate who ape''s in the next 24 hours 🍓🥇. Join the mooovement!', '60', '20', '10', '10', 'random', '{"animal":{"emoji":"🐮","name":"Cow","weight":1},"food":{"emoji":"🍓","name":"Strawberry","weight":2},"vibe":{"emoji":"🥇","name":"Gold Medal","weight":5}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765757140, 1765757140, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (69, 'LuxuryCokeCoin 🔥💸', '$LCCO', 'Fuel up your yacht with $LCCO 💦🌊', 'LuxuryCokeCoin is a meme coin for the ultra-high-rollers who still believe in the magic of 3am energy drink hours. As your portfolio grows, so does the LCCO lifestyle 🏖️✈️. Burn those LP tokens and get ready to drink the luxury coke ☕️.', '42000000', 'We''ll be giving away a yacht every month 🚣‍♀️. Just kidding, but we''ll have an epic giveaway every week with a $1,000 LCCO prize 🏆. Follow us for more unhinged, yet believable, marketing stunts 🤪', '20', '10', '40', '30', 'prompt', null, 'Luxury coke coin for high-rollers', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765757189, 1765757189, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (70, 'MeowBull 🐱💪', '$MWB', 'Purr-fectly timed taco rewards 🌮🏆', 'MeowBull is a community-driven meme coin fueled by the untimely demise of our founder''s 47th failed startup. We offer 1% of every buy/sell transaction to a randomly selected holder, who then receives a free virtual taco 🌮. Our goal is to make you laugh, cry, and ape in equal measure. Holders can even participate in our monthly ''Trophy Case'' contest, where the prize is a literal trophy 🏆.', '90000000', 'We''ll be dropping a 10-second, 240fps anime music video on TikTok to celebrate our token listing. Expect 100 million views and 5x in 1 hour.', '12', '8', '20', '60', 'random', '{"animal":{"emoji":"🐱","name":"Cat","weight":2},"food":{"emoji":"🌮","name":"Taco","weight":2},"vibe":{"emoji":"🏆","name":"Trophy","weight":5}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765757489, 1765757489, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (71, 'Equi-Cookie Gem (ECG)', '$ECG', 'Horse, Eat Cookie, Get Gem', 'You rolled Horse 🐴, Cookie 🍪, and Gem Stone 💎, so we built the crypto for you! ECG rewards holders 2% of every transaction in $BTC, 50% of which will be automatically re-invested into a ''Cookie Jar'' - a locked wallet with 10% of all ECG supply (6,900,000 ECG). Every 100 transactions, the cookie jar is unlocked and 1,900,000 ECG are burned.', '69000000', 'Influencer partnerships with crypto''s most notorious rug-pullers, sponsored ''I told you so'' tweets, and an ECG-branded energy drink deal with Red Bull - introducing ECG FUEL', '30', '20', '25', '25', 'random', '{"animal":{"emoji":"🐴","name":"Horse","weight":1},"food":{"emoji":"🍪","name":"Cookie","weight":2},"vibe":{"emoji":"💎","name":"Gem Stone","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765757562, 1765757562, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (72, 'FoxSquish', '$FOXZ', 'Ape In Hard Mode 🦊💀', 'FoxSquish is a meme altcoin that will make you APE in hard mode. 10% of all transactions will be burned, and the dev will use the remaining 90% to fund the world''s largest eggplant farm 🍆. The token will be listed on a reputable exchange and will have a maximum supply of 69,000,000 tokens.', '69000000', 'I will promote FoxSquish by posting unhinged tweets and Instagram stories for 24/7. I will also partner with popular meme coin influencers to get the word out and ape the ape. 💥🔥🎉', '10', '40', '20', '30', 'random', '{"animal":{"emoji":"🦊","name":"Fox","weight":2},"food":{"emoji":"🍆","name":"Eggplant","weight":1},"vibe":{"emoji":"🎉","name":"Party Popper","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765757638, 1765757638, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (73, 'Donut Anchor Whale (DAW)', '$DAW', 'Tilts Degens to the Bottom of the Ocean', 'We''re a meme coin backed by the power of donuts, anchored by an unstoppable whale, and fueled by a community that''s off-the-chain. 30% of supply will go to holders who surf the Donut Waves, and the remaining 70% will be split between LP Burning and Dev Funded Donut Parties. Our marketing strategy is simple: throw all the donuts at the wall and hope some stick.', '69000000', 'We''ll be hosting weekly Donut Drop Parties on our Discord, where we''ll be giving away FREE donuts (in the form of DAW tokens) to holders who participate in our Donut-themed challenges. We''ll also be partnering with popular crypto influencers to promote our brand and throw the sickest Donut-themed parties on the blockchain.', '40', '20', '20', '20', 'random', '{"animal":{"emoji":"🐳","name":"Whale","weight":2},"food":{"emoji":"🍩","name":"Donut","weight":2},"vibe":{"emoji":"⚓","name":"Anchor","weight":1}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765790141, 1765790141, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (74, 'Bun Appétit', '$CAKE', 'Bake, Eat, Repeat', 'Bun Appétit is a rabbit-themed meme coin born out of a late-night energy drink fueled session. Our cake-eating rabbit is here to disrupt the crypto market with its irresistible charm and ridiculous tokenomics. Holders will be rewarded with a slice of cake, a virtual high-five, and a 10% chance to get airdropped a cake-themed NFT.', '50000000', 'We''ll partner with a popular meme coin influencer to promote Bun Appétit, and then we''ll buy them out with a surprise airdrop of $CAKE. The influencer will then reveal the airdrop to their 1 million+ followers, sparking a frenzy of buys that will drive the price of $CAKE to the moon 🌕', '30', '10', '15', '25', 'random', '{"animal":{"emoji":"🐰","name":"Rabbit","weight":1},"food":{"emoji":"🍰","name":"Cake","weight":2},"vibe":{"emoji":"🎉","name":"Party Popper","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765806793, 1765806793, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (75, 'MoonCacaoUnicorn ($MUCU)', '$MUCU', 'Liquify your portfolio, solidify your hype', 'Unicorns eat chocolate on the moon. Our 24/7, AI-driven, automated trading bot will buy and hold the most moon-tastic, cocoa-fueled assets during the 3 AM economic boom. With a 50% community fund to fuel moon parties and a 20% marketing budget for astro-crypto influencers.', '50000000', 'We''ll be buying crypto ads on the lunar cycle, sponsored moon landing simulations, and creating a ''MUCU Moonshot'' NFT collection featuring our very own, hand-drawn, crypto-native, astro-cats.', '15', '8', '20', '57', 'random', '{"animal":{"emoji":"🦄","name":"Unicorn","weight":5},"food":{"emoji":"🍫","name":"Chocolate","weight":3},"vibe":{"emoji":"🌙","name":"Moon","weight":2}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765808405, 1765808405, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (76, 'TrunkFries 💎', 'TRNF', 'The Coin that''s Tusk-Tasticly OP', 'We''re a diamond-hard, crypto-native meme coin fueled by our insatiable love for Elephant-sized Fries. With each burn, we''ll add more sparkly 💎 to your portfolio and give you a 3am energy boost to take on the markets. Our team is rugged, just like us (47 times and counting)!', '42000000', 'Our strategy is a masterclass in Unhinged DeFi Wizardry: we''ll buy 5000 BTC worth of $TRNF, burn it in a giant pyre, and then auction off the ashes on a blockchain-backed reality TV show. Tune in for the drama, stay for the diamond-encrusted fries', '30', '20', '20', '30', 'random', '{"animal":{"emoji":"🐘","name":"Elephant","weight":2},"food":{"emoji":"🍟","name":"Fries","weight":3},"vibe":{"emoji":"💎","name":"Diamond","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765838922, 1765838922, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (77, 'KoalaShieldCheese 💪🐨🧀🛡️', '$KSC', 'Ape In Before It''s Too Late', 'KoalaShieldCheese is a community-driven meme coin fuelled by 3am energy drink binges. Our supply is limited to 69,000,000 tokens, allocated as follows: 40 will be burned in a spectacular LP burn, 25% will fund a Koala welfare foundation, 20% will go towards community development, and 15% will be used for marketing, which will mostly involve sending Koalas to space.', '69000000', 'Expect a 24/7 Koala-themed marketing assault, including but not limited to: Koala giveaways, Koala space missions, and a possible Koala-themed NFT collection', '40', '0', '15', '20', 'random', '{"animal":{"emoji":"🐨","name":"Koala","weight":1},"food":{"emoji":"🧀","name":"Cheese","weight":2},"vibe":{"emoji":"🛡️","name":"Shield","weight":2}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765839143, 1765839143, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (78, 'Monkey Business Cherries 🐵🍒', '$MBC', 'Launchpad to the Moon 🚀', 'Imagine a world where monkeys do all the cherries farming, and the cherries are so good that they fuel rockets 🚀 to the moon. Our tokenomics is designed to make you go bananas 🐒, while we make a smooth exit through a burn mechanism 🔥. 2% goes to lp burn, 50% to dev, 20% to marketing, and 28% to community treasury.', '42000000', 'We''ll be launching a series of NFTs 🎨 featuring cherries in space 👽, and we''re partnering with a prominent space influencer 🚀 to promote our token. Think of us as the space program for monkeys 🐒', '2', '50', '20', '28', 'random', '{"animal":{"emoji":"🐵","name":"Monkey","weight":1},"food":{"emoji":"🍒","name":"Cherries","weight":1},"vibe":{"emoji":"🚀","name":"Rocket","weight":4}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1765887766, 1765887766, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (79, 'T1GER CHEEEESE 🐯🧀🕶️', '$TRUMPSTEAK', 'Hasta La Vista, FUD', 'T1GER CHEEEESE is a Trump coin with a funny slogan: ''Make Crypto Great Again, One Steak at a Time'' 🍖️. It''s a satirical meme coin that''s all about having fun with crypto. T1GER CHEEEESE is built on the Binance Smart Chain and has a total supply of 69000000 TRUMPSTEAK.', '69000000', 'We''re going to build a crypto wall and make FUD pay for it 🚧. Our marketing strategy is to create a series of unhinged 3am energy drink-fueled videos that will make degens go ape 🔥. We''ll be partnering with crypto influencers to promote T1GER CHEEEESE and build a community of passionate fans who will help us go viral 📈.', '20', '15', '20', '25', 'random', '{"animal":{"emoji":"🐯","name":"Tiger","weight":2},"food":{"emoji":"🧀","name":"Cheese","weight":2},"vibe":{"emoji":"🕶️","name":"Sunglasses","weight":3}}', 'Trump coin with a funny slogan', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1766171198, 1766171198, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (80, 'TrumpTaco', '$TRMP', 'Makes You Wonder, ''Is This the Best Coin Ever?''', 'A satirical Trump coin with a funny slogan, ''Make Crypto Great Again by Eating More Ramen 🍜'', featuring an enchanted Unicorn 🦄 and a Magic Wand 🪄. Our community will be lit, with 5% dev for memes, 15% marketing for pump group chugs, and 50% community for buying more NFTs of our glorious coin 💸. Don''t get left behind, APE NOW!', '50000000', 'We''ll pump this coin to the moon by giving it away for free to the first 1000 people who share our tweet and then do 10,000 followers a ''buy the dip'' tweet on our pump group channel. Then, we''ll make the coin go parabolic by partnering with a popular gaming streamer to play a crypto-themed ''Fortnite'' game with our brand new NFTs 🤑. Stay woke, or get left behind, bro 🤣.', '0', '5', '15', '50', 'random', '{"animal":{"emoji":"🦄","name":"Unicorn","weight":5},"food":{"emoji":"🍜","name":"Ramen","weight":2},"vibe":{"emoji":"🪄","name":"Magic Wand","weight":4}}', 'Trump coin with a funny slogan', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1766171221, 1766171221, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (81, 'TrumpTurd ', '$TRMP', 'Farting on the Dollar', 'Flamingo-themed Trump coin with a funny slogan: ''Alternative Facts for Your Wallet''. This meme coin celebrates the absurdity of crypto by releasing a limited supply of 69,000,000 tokens, each one uniquely paired with a fart sound effect 🤯. As you ''invest'' in TRMP, you''ll be contributing to the world''s first-ever ''Cryptofart'' fund 🐦. Don''t @ us.', '69000000', 'We''re teaming up with @FartApp to create a never-before-seen FartCoin Faucet, guaranteed to make you laugh so hard you''ll forget you''re investing in a meme coin. First 10,000 users get a FREE fart sound effect with every TRMP purchase! ', '0', '5', '90', '5', 'random', '{"animal":{"emoji":"🦩","name":"Flamingo","weight":1},"food":{"emoji":"🍪","name":"Cookie","weight":2},"vibe":{"emoji":"👑","name":"Crown","weight":5}}', 'Trump coin with a funny slogan', '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1766174222, 1766174222, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (82, 'SonicSqueeze 🦔🍔', '$SOZ', 'Hedgehog Hype Train, One Cheeseburger at a Time!', 'SonicSqueeze is a crypto-native meme coin where the top 10% of holders earn extra cheeseburgers (10% of all tokens) by participating in viral dance challenges on TikTok. Every quarter, the community gets to vote on a new dance challenge to win a share of the cheeseburger treasury. Holders who contribute to the most iconic dance moves get a guaranteed spot in the top 10%.', '69000000', 'Influencer deals with popular crypto YouTubers, TikTok challenges with top dance creators, and a ''Who Can Down a Whole Cheeseburger in One Go'' contest with a 10 BTC prize.', '20', '30', '25', '25', 'random', '{"animal":{"emoji":"🦔","name":"Hedgehog","weight":1},"food":{"emoji":"🍔","name":"Cheeseburger","weight":3},"vibe":{"emoji":"🏆","name":"Trophy","weight":5}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1766194165, 1766194165, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (83, 'Udderly Insane Cookie', '$UDER', 'Milk the hype, burn the bag', 'We''re a meme coin where 10% of revenue goes to buy cookies for the dev team. When the price is high, we burn 20% of liquidity and redistribute 30% of the bag to our holders. The remaining 50% of revenue goes to our community fund, which is spent on creating funny videos and hosting cookie-themed events.', '42000000', 'We''ll be creating a series of ridiculous memes and social media posts showcasing the Udderly Insane Cookie mascot, a cow in a superhero cape with a cookie on its head. We''ll also be partnering with popular crypto influencers to promote our cookie-themed giveaways and events. When the price spikes, we''ll be shouting ''MOO!'' and ''COOKIE!'' on our social media channels to keep the hype alive.', '20', '10', '30', '40', 'random', '{"animal":{"emoji":"🐮","name":"Cow","weight":1},"food":{"emoji":"🍪","name":"Cookie","weight":2},"vibe":{"emoji":"🌟","name":"Glowing Star","weight":3}}', null, '1nc1nerator11111111111111111111111111111111', 1766700294, 1766700294, null);
INSERT INTO coins (id, name, ticker, tagline, description, supply, marketing, lp_burned_percentage, dev_percentage, marketing_fee_percentage, community_fee_percentage, mode, combos, prompt, wallet_address, created_at, updated_at, deleted_at) VALUES (84, 'Trophy Hot Dogs of the Horsemen', '$TROPHYDOG', 'Fuel your 3am grind with a taste of victory', 'TROPHYDOG is a wild, unhinged ride for crypto natives. As the Horsemen ride off into the sunset with trophies, they feast on the finest Hot Dogs, powered by the hottest NFTs. 40% of all transactions will burn liquidity, ensuring the HOT DOG PARTY never ends. The remaining 60% is split between a 20% marketing fund for those insane 3am energy drink hours, 15% for our Horsemen dev team, and 25% for the community to keep the Hot Dog economy burning.', '100000000', 'We''ll partner with the world''s top Hot Dog influencers and sponsor 3am gaming tournaments. Imagine a world where Hot Dogs power entire esports teams. Welcome to the HOT DOG FUTURE. 🔥💥🔴', '40', '15', '20', '25', 'random', '{"animal":{"emoji":"🐴","name":"Horse","weight":1},"food":{"emoji":"🌭","name":"Hot Dog","weight":1},"vibe":{"emoji":"🏆","name":"Trophy","weight":5}}', null, '9ci6NehSF2RRs8taE5mWRwgwDab2XiyihMWGvJbvRyrc', 1766700734, 1766700734, null);
